/* 【糯叽机】无声回信（黑）by黛 — SullyOS 白框适配
   原作：黑白连发气泡／黑色头像圈／磨砂悬浮顶栏／推文式心象／贴图转账。
   仅使用糯米机真实开放的 .sully-* 接口；私聊与群聊共用。 */
.sully-chat-root {
  --silent-ink:#1a1a1a;
  --silent-paper:#fff;
  --silent-muted:#858585;
  color:#1a1a1a;
}
.sully-chat-root .sully-chat-header {
  position:relative!important;
  min-width:0!important;
  background:rgba(255,255,255,.34)!important;
  border-bottom:0!important;
  backdrop-filter:blur(9px) saturate(115%);
  -webkit-backdrop-filter:blur(9px) saturate(115%);
  box-shadow:none!important;
  gap:5px!important;
}
.sully-chat-root .sully-chat-back {
  flex-shrink:0!important;
  width:35px!important;height:35px!important;
  border-radius:50%!important;
  background:rgba(255,255,255,.84)!important;
  box-shadow:0 2px 8px #00000014!important;
  color:#1a1a1a!important;
}
.sully-chat-root .sully-chat-info {
  min-width:0!important;max-width:100%!important;
}
.sully-chat-root .sully-chat-name {
  color:#1a1a1a!important;
  font-size:14px!important;
  font-weight:750!important;
  max-width:100%!important;
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
}
.sully-chat-root .sully-chat-status {
  color:#898989!important;
  font-size:10px!important;
}
.sully-chat-root .sully-chat-avatar {
  width:30px!important;height:30px!important;
  border-radius:50%!important;
  object-fit:cover;
  border:1.5px solid #1a1a1a!important;
  padding:2px;background:#fff;
}
.sully-chat-root .sully-chat-trigger,
.sully-chat-root .sully-chat-token {
  color:#1a1a1a!important;
}
.sully-chat-root .sully-chat-buffs button {
  background:#ffffffc9!important;
  color:#222!important;border:1px solid #dddddd!important;
  border-radius:20px!important;
}
/* 白色玻璃输入胶囊。保留每个真实按钮与编辑框的点击区域。 */
.sully-chat-root .sully-chat-inputbar {
  background:rgba(255,255,255,.34)!important;
  border-top:0!important;
  backdrop-filter:blur(9px);-webkit-backdrop-filter:blur(9px);
  box-shadow:none!important;
}
.sully-chat-root .sully-chat-composer {
  background:rgba(255,255,255,.83)!important;
  border:1px solid #e8e8e8!important;
  border-radius:28px!important;
  box-shadow:inset 0 1px 2px #fff,0 3px 10px #0000000c!important;
  min-width:0!important;
}
.sully-chat-root .sully-chat-input-wrap {
  min-width:0!important;
  border-radius:24px!important;
}
.sully-chat-root .sully-chat-textarea {
  color:#1a1a1a!important;
  min-width:0!important;
  font-size:13px!important;
}
.sully-chat-root .sully-chat-textarea::placeholder {color:#9a9a9a!important;}
.sully-chat-root .sully-chat-actions-button {
  color:#1a1a1a!important;flex-shrink:0!important;
}
.sully-chat-root .sully-chat-send-button {
  color:#fff!important;background:#1a1a1a!important;
  border:1px solid #1a1a1a!important;border-radius:50%!important;
  box-shadow:none!important;flex-shrink:0!important;
}
.sully-chat-root .sully-chat-panel {
  background:rgba(255,255,255,.94)!important;
  color:#1a1a1a!important;
  border:1px solid #ececec!important;
}
/* 连发保持 2px 节奏；模块卡片、红包、系统提示不强迫改成文字气泡。 */
.sully-chat-root .sully-chat-message:not(.sully-chat-message-module) {
  margin-bottom:4px!important;min-width:0;
}
.sully-chat-root .sully-chat-message-group-last:not(.sully-chat-message-module) {
  margin-bottom:15px!important;
}
.sully-chat-root .sully-chat-message-content {
  min-width:0!important;
  max-width:min(82%,calc(100% - 43px))!important;
}
.sully-chat-root .sully-chat-message-module .sully-chat-message-content {
  max-width:100%!important;
}
.sully-chat-root .sully-bubble-user,
.sully-chat-root .sully-bubble-ai {
  max-width:100%;overflow-wrap:anywhere;
  font-size:13px!important;
  line-height:1.38!important;
  padding:7px 11px!important;
  border:0!important;
  box-shadow:none!important;
  background-image:none!important;
}
.sully-chat-root .sully-bubble-user {
  background:#1a1a1a!important;
  color:#fff!important;
  border-radius:18px!important;
}
.sully-chat-root .sully-bubble-ai {
  background:#eee!important;
  color:#101010!important;
  border-radius:18px!important;
}
.sully-chat-root .sully-bubble-user.sully-bubble-group-first:not(.sully-bubble-group-last) {border-bottom-right-radius:5px!important;}
.sully-chat-root .sully-bubble-user.sully-bubble-group-last:not(.sully-bubble-group-first) {border-top-right-radius:5px!important;}
.sully-chat-root .sully-bubble-user:not(.sully-bubble-group-first):not(.sully-bubble-group-last) {border-radius:18px 5px 5px 18px!important;}
.sully-chat-root .sully-bubble-ai.sully-bubble-group-first:not(.sully-bubble-group-last) {border-bottom-left-radius:5px!important;}
.sully-chat-root .sully-bubble-ai.sully-bubble-group-last:not(.sully-bubble-group-first) {border-top-left-radius:5px!important;}
.sully-chat-root .sully-bubble-ai:not(.sully-bubble-group-first):not(.sully-bubble-group-last) {border-radius:5px 18px 18px 5px!important;}
.sully-chat-root .sully-bubble-user::before,
.sully-chat-root .sully-bubble-user::after,
.sully-chat-root .sully-bubble-ai::before,
.sully-chat-root .sully-bubble-ai::after {content:none!important;display:none!important;}
/* 头像套独立黑色细圈、留白与小加号；不要位移到气泡上。 */
.sully-chat-root .sully-chat-avatar-wrap {
  position:relative!important;overflow:visible!important;
  flex-shrink:0!important;
  padding:2px!important;
  background:#fff!important;
  border:1.5px solid #1a1a1a!important;
  border-radius:50%!important;
}
.sully-chat-root .sully-chat-avatar-wrap .sully-chat-message-avatar-img {
  width:100%!important;height:100%!important;
  border-radius:50%!important;object-fit:cover!important;
}
.sully-chat-root .sully-chat-avatar-wrap::after {
  content:"+"!important;
  position:absolute!important;
  right:-4px!important;bottom:-3px!important;
  width:13px!important;height:13px!important;
  display:flex!important;align-items:center!important;justify-content:center!important;
  color:#fff!important;background:#1a1a1a!important;
  font:700 10px/1 system-ui!important;
  border:1.5px solid white!important;border-radius:50%!important;
  pointer-events:none!important;
}
.sully-chat-root .sully-chat-avatar-frame {display:none!important;}
/* 保持真实引用内容和翻译功能：仅改变颜色、外框，不能隐藏。 */
.sully-chat-root .sully-chat-reply {
  color:#444!important;
  background:rgba(0,0,0,.035)!important;
  border-left:2px solid #1a1a1a!important;
  border-radius:4px 10px 10px 4px!important;
  padding:5px 9px!important;
  font-size:11px!important;line-height:1.35!important;
  opacity:1!important;
  max-width:100%!important;
}
.sully-chat-root .sully-bubble-user .sully-chat-reply {
  color:#eeeeee!important;
  background:rgba(255,255,255,.14)!important;
  border-left-color:#fff!important;
}
.sully-chat-root .sully-bubble-ai .sully-chat-reply {
  color:#444!important;
  background:rgba(0,0,0,.035)!important;
  border-left-color:#1a1a1a!important;
}
.sully-chat-root .sully-chat-message .sully-qq-quote,
.sully-chat-root .sully-chat-message .sully-facebook-reply {
  border-color:#1a1a1a!important;
  background:#f2f2f2!important;color:#242424!important;
  border-radius:9px!important;font-size:11px!important;
}
.sully-chat-root .sully-voice-bar {
  max-width:100%!important;
  border-radius:15px!important;
}
.sully-chat-root .sully-voice-bar-shell {min-width:0!important;}
.sully-chat-root .sully-voice-bar-transcript {
  font-size:11px!important;line-height:1.5!important;
}
/* “推特卡”思考：不伪造角色名，保留原生标题/展开正文与按钮。 */
.sully-chat-root .sully-psyche-card {
  position:relative!important;
  background:#fff!important;
  color:#0f1419!important;
  border:1px solid #e7e9eb!important;
  box-shadow:0 3px 9px #00000009!important;
  border-radius:15px!important;
  padding:12px!important;
  min-width:0!important;
}
.sully-chat-root .sully-psyche-title {
  color:#1d9bf0!important;
  letter-spacing:.02em!important;
  font-size:12px!important;
}
 .sully-chat-root .sully-psyche-preview {
  color:#848d95!important;font-size:12px!important;
}
.sully-chat-root .sully-psyche-status {
  color:#536471!important;text-shadow:none!important;
}
.sully-chat-root .sully-psyche-body {
  color:#0f1419!important;
  font-size:13px!important;line-height:1.65!important;
  white-space:pre-wrap!important;
}
/* 转账原稿是黑色贴图卡；增加渐变兜底，保留状态和交互。 */
.sully-chat-root .sully-chat-transfer-card {
  width:min(245px,100%)!important;
  min-height:110px!important;
  max-width:100%!important;
  background-color:#1a1a1a!important;
  background-image:linear-gradient(0deg,rgba(0,0,0,.72),rgba(0,0,0,.10)),url("https://i.imgant.com/v2/0iF6jgl.jpeg")!important;
  background-size:100% 100%,100% 100%!important;
  background-position:center!important;
  border:1px solid #373737!important;
  border-radius:10px!important;
  color:#fff!important;
  box-shadow:0 3px 10px #00000024!important;
}
.sully-chat-root .sully-chat-transfer-card .sully-chat-transfer-header {
  margin-bottom:5px!important;
}
.sully-chat-root .sully-chat-transfer-brand {
  color:#f4f4f4!important;font-size:11px!important;
}
.sully-chat-root .sully-chat-transfer-card .sully-chat-transfer-amount {
  color:#fff!important;
  font-size:23px!important;font-weight:800!important;
  text-shadow:0 1px 3px #0006!important;
  overflow-wrap:anywhere;
}
.sully-chat-root .sully-chat-transfer-card .sully-chat-transfer-note,
.sully-chat-root .sully-chat-transfer-card .sully-chat-transfer-recipient {
  color:#f3f3f3!important;font-size:10px!important;
  text-shadow:0 1px 2px #0008!important;
}
.sully-chat-root .sully-chat-transfer-card .sully-chat-transfer-status {
  color:#fff!important;background:#ffffff3d!important;
  border:1px solid #ffffff55!important;
  border-radius:10px!important;
}
.sully-chat-root .sully-chat-transfer-receipt {
  background:#eee!important;color:#1a1a1a!important;
  border:1px solid #d6d6d6!important;
  border-radius:12px!important;
  max-width:100%!important;
}
.sully-chat-root .sully-chat-transfer-dialog {
  background:#fff!important;color:#1a1a1a!important;
  border-radius:18px!important;
}
.sully-chat-root .sully-chat-transfer-accept {
  background:#1a1a1a!important;color:#fff!important;
}
.sully-chat-root .sully-chat-transfer-return {
  background:#eee!important;color:#222!important;
}

/* 群聊采用独立消息渲染器：与私聊同色，但保留真实群成员姓名和红包操作。 */
.sully-chat-root .sully-chat-message-sender {
  color:#777!important;font-size:10px!important;
  font-weight:600!important;line-height:1.4!important;
}
.sully-chat-root .sully-chat-message-avatar:not(.sully-chat-avatar-wrap) {
  position:relative!important;overflow:visible!important;
  padding:2px!important;background:#fff!important;
  border:1.5px solid #1a1a1a!important;
  border-radius:50%!important;flex-shrink:0!important;
}
.sully-chat-root .sully-chat-message-avatar:not(.sully-chat-avatar-wrap) .sully-chat-message-avatar-img {
  border-radius:50%!important;object-fit:cover!important;
}
.sully-chat-root .sully-chat-message-avatar:not(.sully-chat-avatar-wrap)::after {
  content:"+"!important;pointer-events:none!important;
  position:absolute!important;right:-4px!important;bottom:-3px!important;
  display:flex!important;align-items:center!important;justify-content:center!important;
  width:13px!important;height:13px!important;
  font:700 10px/1 system-ui!important;color:#fff!important;
  background:#1a1a1a!important;border:1.5px solid #fff!important;
  border-radius:50%!important;z-index:3!important;
}
.sully-chat-root .sully-chat-group-packet {
  width:min(235px,100%)!important;min-width:0!important;
  background:#1a1a1a!important;color:#fff!important;
  border:1px solid #303030!important;border-radius:12px!important;
  box-shadow:0 3px 10px #00000021!important;
  overflow:hidden!important;
}
.sully-chat-root .sully-chat-group-packet-receipt {
  background:#eee!important;color:#292929!important;
  border:1px solid #d6d6d6!important;border-radius:12px!important;
  max-width:100%!important;overflow-wrap:anywhere!important;
}

/* 图片和表情不统一盖黑底，避免媒体内容被遮挡。 */
.sully-chat-root .sully-chat-card[data-card-kind="transfer"] .sully-chat-card-surface {max-width:100%;}
.sully-chat-root .sully-chat-card[data-card-kind="image"] img,
.sully-chat-root .sully-emoji-msg img {max-width:100%;height:auto;object-fit:contain;}
@media(max-width:370px) {
 .sully-chat-root .sully-chat-header {gap:3px!important;}
 .sully-chat-root .sully-chat-back {width:32px!important;height:32px!important;}
 .sully-chat-root .sully-chat-name {font-size:12px!important;}
 .sully-chat-root .sully-chat-message-content {max-width:min(85%,calc(100% - 39px))!important;}
 .sully-chat-root .sully-chat-transfer-card {width:min(228px,100%)!important;}
}
